/**
 * Sent when the session closes (client `end`, inactivity timeout, max
 * duration, or server error). Keyed by `request_id` (not `session_id`).
 */
export interface RealtimeSessionEnd {
    event: "session.end";
    /** Per-connection correlation id */
    request_id: string;
    /** Total wall-clock session duration in seconds */
    total_duration_s?: number | undefined;
    /** Number of utterances processed during the session */
    total_utterances?: number | undefined;
    /** Total audio duration processed in seconds (the billed audio quantity) */
    audio_duration_s?: number | undefined;
}
